            "settings.appearance.desc": "Hell, dunkel oder die Systemeinstellung von Mac oder PC für die Axis-Oberfläche (Tabs, Seitenleiste, Pop-ups). Ändert nicht dieses Einstellungsfenster, die Seite „Neuer Tab“ oder den KI-Chat - die bleiben dunkel.",
