            "settings.siteTheme.title": "Website-Designfarbe",
            "settings.siteTheme.desc": "Lässt Axis die Browser-Designfarbe an die aktuelle Website anpassen. Jederzeit deaktivieren, um wieder Ihre gespeicherte Designfarbe zu verwenden.",
            "settings.windowChrome.title": "Fenstertransparenz",
            "settings.windowChrome.desc": "Wie stark Ihr Hintergrundbild oder Desktop durch den Browserrahmen (Tab-Leiste, Seitenleiste, Unschärfe) scheint. Links: vollständig undurchsichtig. Rechts: am transparentesten. Die Mitte ist die Standardeinstellung.",
